// 可直接使用同级数据池字段名作为变量（无需形参）
// return 的值即为该字段的计算值
const info = getDeviceInfo()
if($props.isFillScreen && info.platform !== 'h5'){
  return info.statusBarHeight
}
return 0

// 可直接使用同级数据池字段名作为变量（无需形参）
// return 的值即为该字段的计算值
const info = getDeviceInfo()
if(info.platform === 'h5'){
  return 45
}
return offsetTop + info.menuButton.height + (info.menuButton.top-info.statusBarHeight)+5
